let b = $('🔔 Pedido da TV (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const base = String($('🔔 Pedido da TV (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
return [{ json: { b, base, cardapio: b.fonte === 'cardapio' ? String(b.cardapio || '').trim().toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 64) || 'nenhum' : 'nenhum' } }];

// Regras da TV do estabelecimento (as mesmas na criação, na TV, no controle do celular e na oferta nova com IA).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const tvT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
const tvL = (v, max) => tvT(v, max).replace(/[<>{}]/g, '');
const tvEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const tvBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
// 9,90 · 9.90 · R$ 1.250,00 · 12 ➜ número; vazio/errado = null
const tvNum = v => {
  if (typeof v === 'number') return isFinite(v) && v >= 0 ? Math.round(v * 100) / 100 : null;
  let s = String(v ?? '').replace(/[^\d,.]/g, '');
  if (!s) return null;
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.'); else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, ''); else s = s.replace(/,/g, '');
  const n = Number(s); return isFinite(n) && n >= 0 && n < 100000 ? Math.round(n * 100) / 100 : null;
};
// emoji: o primeiro do texto; os novos demais (U+1FA70–1FAFF) não aparecem em TV/Windows antigos
const tvEmoji = (v, padrao) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m && !/[\u{1FA70}-\u{1FAFF}]/u.test(m[0]) ? m[0] : padrao; };
const TV_PERIODOS = { cafe: { nome: 'Café da manhã', ini: '06:00', fim: '11:00' }, almoco: { nome: 'Almoço', ini: '11:00', fim: '15:00' },
  tarde: { nome: 'Tarde', ini: '15:00', fim: '18:00' }, noite: { nome: 'Noite', ini: '18:00', fim: '23:59' } };
const TV_TIPOS = { padaria: 'Padaria', lanchonete: 'Lanchonete', restaurante: 'Restaurante', cafeteria: 'Cafeteria', acai: 'Açaí e sorveteria', pizzaria: 'Pizzaria',
  academia: 'Academia', salao: 'Salão / barbearia', clinica: 'Clínica / consultório', loja: 'Loja', outro: 'Outro' };
const TV_PALETAS = {
  escuro: { nome: 'Escuro elegante', fundo: '#111315', sup: '#1C1F23', tx: '#F5F3EF', cor: '#F2B33D', escuro: true },
  vibrante: { nome: 'Vibrante', fundo: '#1A1033', sup: '#26184A', tx: '#FFFFFF', cor: '#FF5C8A', escuro: true },
  natural: { nome: 'Natural', fundo: '#F3EFE6', sup: '#FFFFFF', tx: '#2B2620', cor: '#2F7D4F', escuro: false },
  claro: { nome: 'Claro', fundo: '#F7F7F5', sup: '#FFFFFF', tx: '#17181A', cor: '#D2462E', escuro: false },
};
const tvHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const tvLum = h => tvHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const tvContraste = (a, b) => { const x = tvLum(a), y = tvLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const tvMistura = (a, b, k) => { const x = tvHex(a), y = tvHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores com contraste garantido (TV é vista de longe: destaque e preço legíveis no fundo, botão/etiqueta com texto legível)
function tvTokens(paleta, cor) {
  const p = TV_PALETAS[paleta] || TV_PALETAS.escuro;
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : p.cor;
  const longe = p.escuro ? '#FFFFFF' : '#000000';
  let forte = c;
  for (let i = 0; i < 16 && tvContraste(forte, p.fundo) < 4.5; i++) forte = tvMistura(forte, longe, 0.12);
  const tinta = tvContraste('#FFFFFF', c) >= tvContraste('#111111', c) ? '#FFFFFF' : '#111111';
  let selo = c;
  for (let i = 0; i < 16 && tvContraste(tinta, selo) < 4.5; i++) selo = tvMistura(selo, tinta === '#FFFFFF' ? '#000000' : '#FFFFFF', 0.1);
  let mu = tvMistura(p.tx, p.fundo, 0.35);
  for (let i = 0; i < 10 && tvContraste(mu, p.fundo) < 4.5; i++) mu = tvMistura(mu, p.tx, 0.2);
  return { paleta: paleta in TV_PALETAS ? paleta : 'escuro', fundo: p.fundo, sup: p.sup, tx: p.tx, mu, cor: c, forte, selo, tinta, linha: tvMistura(p.tx, p.fundo, 0.8), escuro: p.escuro };
}
// "Categoria | Item | Preço | descrição" (uma linha por item; também aceita ; ou tab)
function tvParseItens(texto) {
  const cats = [];
  String(texto || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean).slice(0, 200).forEach(l => {
    const p = l.split(/\s*[|;\t]\s*/);
    if (p.length < 3) return;
    const preco = tvNum(p[2]);
    const nome = tvL(p[1], 60), cn = tvL(p[0], 40) || 'Cardápio';
    if (!nome || preco === null) return;
    let c = cats.find(x => x.nome.toLowerCase() === cn.toLowerCase());
    if (!c) { c = { id: 'c' + (cats.length + 1), nome: cn, emoji: '', itens: [] }; cats.push(c); }
    c.itens.push({ id: c.id + 'i' + (c.itens.length + 1), nome, preco, descricao: tvL(p[3], 90), esgotado: false });
  });
  return cats.slice(0, 16);
}
// trava: valor em R$ que não está nos preços do dono sai da frase
function tvGuarda(txt, valores, onde, problemas) {
  return String(txt || '').split(/(?<=[.!?…])\s+/).filter(f => {
    const vs = (f.match(/R\$\s?\d[\d.]*(?:,\d{1,2})?/g) || []).map(x => Math.round(tvNum(x) * 100)).filter(n => !valores.has(n));
    if (vs.length && problemas) problemas.push(`${onde}: tirei a frase com ${vs.map(v => tvBRL(v / 100)).join(', ')}, que não está nos seus preços ("${tvT(f, 70)}")`);
    return !vs.length;
  }).join(' ').trim();
}
// textos da redatora (ou da revisora) no formato da tela, com tamanho máximo e o que faltar preenchido
function tvTextos(r, V) {
  r = r && typeof r === 'object' ? r : {};
  const o = x => (x && typeof x === 'object' ? x : {}), bv = o(r.boas_vindas), wz = o(r.whatsapp), im = o(r.imagens);
  const ro = Array.isArray(r.ofertas) ? r.ofertas.filter(x => x && typeof x === 'object') : [];
  const avisos = (Array.isArray(r.avisos) ? r.avisos : []).map(a => tvL(a, 90)).filter(Boolean);
  return {
    boas_vindas: { titulo: tvL(bv.titulo, 40) || `Bem-vindo à ${V.negocio.nome}`, texto: tvL(bv.texto, 110) },
    ofertas: Object.fromEntries(V.ofertas.map((of, i) => { const x = ro.find(y => y.k === of.k) || ro[i] || {};
      return [of.k, { titulo: tvL(x.titulo, 34) || of.produto, subtitulo: tvL(x.subtitulo, 80) || of.descricao, selo: tvL(x.selo, 22) || 'Oferta', chamada: tvL(x.chamada, 40) }]; })),
    avisos: V.avisos.map((a, i) => avisos[i] || a),
    whatsapp: { titulo: tvL(wz.titulo, 36) || 'Peça pelo WhatsApp', texto: tvL(wz.texto, 80) || 'Aponte a câmera do celular para o QR code' },
    imagens: Object.fromEntries(V.ofertas.map(of => [of.k, tvT(im[of.k], 600)])),
  };
}
// o que a TV recebe (sem a chave do controle); imagens com o endereço completo
function tvPublico(t, ARQ) {
  return { id: t.id, versao: t.versao, negocio: t.negocio, categorias: t.categorias, grade: t.grade, destaques: t.destaques || [], periodos: t.periodos, periodo_forcado: t.periodo_forcado || 'auto',
    ofertas: (t.ofertas || []).filter(o => o.ativa).map(o => ({ k: o.k, produto: o.produto, titulo: o.titulo, subtitulo: o.subtitulo, selo: o.selo, chamada: o.chamada, de: o.de, por: o.por, quando: o.quando, imagem: o.imagem ? ARQ + o.imagem : '' })),
    avisos: t.avisos || [], boas_vindas: t.boas_vindas, whatsapp_txt: t.whatsapp_txt, tela: t.tela, cores: t.cores, iniciais: t.iniciais };
}
// período agora (hora de Brasília); "auto" segue o relógio
function tvPeriodoAgora(periodos, forcado, ms = Date.now()) {
  if (forcado && forcado !== 'auto' && periodos[forcado]) return forcado;
  const hm = new Date(ms - 3 * 3600e3).toISOString().slice(11, 16);
  return Object.keys(periodos).find(k => periodos[k].ativo && periodos[k].ini <= hm && hm < periodos[k].fim) || '';
}

// Confere o pedido do dono: itens (do Cardápio com IA ou colados), ofertas, avisos, períodos e o jeito da tela. Cria o código da TV e a chave do controle.
const crypto = require('crypto');
const P = $('🧩 Lê o pedido').first().json, b = P.b;
let menu = null;
try { menu = JSON.parse($('📖 Lê o cardápio (importar)').first().json.menu || 'null'); } catch (e) {}
const erros = [];
const nome = tvL(b.nome, 50);
if (nome.length < 2) erros.push('Diga o nome do negócio.');
const tipo = TV_TIPOS[b.tipo] ? b.tipo : 'outro';
let categorias = [], combos = [], origem = 'lista';
if (b.fonte === 'cardapio') {
  if (!menu) erros.push('Não achei esse código de cardápio. Confira (é o que vem depois de "c=" no link do cardápio).');
  else {
    origem = 'cardapio';
    categorias = (Array.isArray(menu.categorias) ? menu.categorias : []).slice(0, 16).map((c, i) => ({ id: 'c' + (i + 1), nome: tvL(c && c.nome, 40), emoji: tvEmoji(c && c.emoji, ''),
      itens: (Array.isArray(c && c.itens) ? c.itens : []).slice(0, 40).map((it, j) => ({ id: `c${i + 1}i${j + 1}`, nome: tvL(it && it.nome, 60), preco: tvNum(it && it.preco), descricao: tvL(it && it.descricao, 90), esgotado: false }))
        .filter(it => it.nome && it.preco !== null) })).filter(c => c.nome && c.itens.length);
    combos = (Array.isArray(menu.combos) ? menu.combos : []).slice(0, 6).map(k => ({ produto: tvL(k && k.nome, 60), descricao: tvL(k && k.descricao, 90), por: tvNum(k && k.preco), de: tvNum(k && k.soma) }))
      .filter(k => k.produto && k.por !== null);
  }
} else categorias = tvParseItens(b.itens);
if (!categorias.length && !erros.length) erros.push('Coloque os itens (um por linha: Categoria | Item | Preço) ou importe do Cardápio.');
// ofertas do dono; sem nenhuma, os combos do cardápio viram oferta
let ofertas = (Array.isArray(b.ofertas) ? b.ofertas : []).slice(0, 6).map(o => ({ produto: tvL(o && o.produto, 60), descricao: tvL(o && o.descricao, 90), de: tvNum(o && o.de), por: tvNum(o && o.por), quando: tvL(o && o.quando, 60) }))
  .filter(o => o.produto && o.por !== null);
if (!ofertas.length) ofertas = combos.slice(0, 3).map(k => ({ ...k, quando: '' }));
ofertas = ofertas.map((o, i) => ({ k: 'o' + (i + 1), ...o, de: o.de !== null && o.de > o.por ? o.de : null, ativa: true }));
const avisos = String(b.avisos || '').split(/\r?\n/).map(a => tvL(a, 90)).filter(a => a.length >= 3).slice(0, 6);
const hhmm = (v, p) => /^([01]\d|2[0-3]):[0-5]\d$/.test(v || '') ? v : p;
const pin = b.periodos && typeof b.periodos === 'object' ? b.periodos : {};
const periodos = Object.fromEntries(Object.entries(TV_PERIODOS).map(([k, p]) => [k, { nome: p.nome, ativo: pin[k] ? pin[k].ativo !== false : true, ini: hhmm(pin[k] && pin[k].ini, p.ini), fim: hhmm(pin[k] && pin[k].fim, p.fim) }]));
if (!Object.values(periodos).some(p => p.ativo)) Object.values(periodos).forEach(p => { p.ativo = true; });
const videos = (Array.isArray(b.videos) ? b.videos : String(b.videos || '').split(/\s+/)).map(v => String(v || '').trim()).filter(v => /^https:\/\/[^\s"'<>]{8,400}$/.test(v)).slice(0, 3);
let zap = String(b.whatsapp || '').replace(/\D/g, '');
if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
if (zap.length < 12 || zap.length > 13) zap = '';
const instagram = String(b.instagram || '').replace(/^@/, '').replace(/[^A-Za-z0-9._]/g, '').slice(0, 30);
const corCardapio = menu && menu.design && /^#[0-9a-fA-F]{6}$/.test(menu.design.primaria || '') ? menu.design.primaria : '';
const tela = { orientacao: b.orientacao === 'vertical' ? 'vertical' : 'horizontal', segundos: Math.max(6, Math.min(30, parseInt(b.segundos, 10) || 10)),
  paleta: TV_PALETAS[b.paleta] ? b.paleta : 'escuro', cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? b.cor : corCardapio, relogio: b.relogio !== false, letreiro: b.letreiro !== false,
  videos, imagens_ia: b.imagens_ia !== false && ofertas.length > 0 };
const slug = nome.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 30).replace(/-+$/, '') || 'tela';
const id = `${slug}-${crypto.randomBytes(2).toString('hex')}`;
const chave = crypto.randomBytes(16).toString('hex');
const resumo_ia = `NEGÓCIO: ${nome} (${TV_TIPOS[tipo]})
CATEGORIAS E ITENS:
${categorias.map(c => `${c.id}. ${c.nome}: ${c.itens.map(i => `[${i.id}] ${i.nome} ${tvBRL(i.preco)}`).join('; ')}`).join('\n')}
PERÍODOS ABERTOS: ${Object.entries(periodos).filter(([, p]) => p.ativo).map(([k, p]) => `${k} = ${p.nome} ${p.ini}–${p.fim}`).join('; ')}
OFERTAS DO DONO:
${ofertas.map(o => `${o.k}. ${o.produto}${o.descricao ? ' (' + o.descricao + ')' : ''} — ${o.de ? 'de ' + tvBRL(o.de) + ' ' : ''}por ${tvBRL(o.por)}${o.quando ? ' — vale: ' + o.quando : ''}`).join('\n') || '(nenhuma)'}
AVISOS DO DONO:
${avisos.map(a => '- ' + a).join('\n') || '(nenhum)'}
WHATSAPP PARA PEDIDOS: ${zap ? 'sim' : 'não'}`;
return [{ json: {
  valido: erros.length === 0, erros, id, chave, criado_em: Date.now(), origem, negocio: { nome, tipo, whatsapp: zap, instagram }, categorias, ofertas, avisos, periodos, tela, resumo_ia,
  link: `${P.base}/webhook/tela/${id}/tv`, controle: `${P.base}/webhook/tela-controle?id=${id}&chave=${chave}`, chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

