// "Categoria | Item | Preço | descrição" (uma linha por item; também aceita ; ou tab)
function tvParseItens(texto) {
  const cats = [];
  String(texto || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean).slice(0, 200).forEach(l => {
