  });
  return cats.slice(0, 16);
}
// trava: valor em R$ que não está nos preços do dono sai da frase
function tvGuarda(txt, valores, onde, problemas) {
  return String(txt || '').split(/(?<=[.!?…])\s+/).filter(f => {
