// período agora (hora de Brasília); "auto" segue o relógio
function tvPeriodoAgora(periodos, forcado, ms = Date.now()) {
  if (forcado && forcado !== 'auto' && periodos[forcado]) return forcado;
  const hm = new Date(ms - 3 * 3600e3).toISOString().slice(11, 16);
  return Object.keys(periodos).find(k => periodos[k].ativo && periodos[k].ini <= hm && hm < periodos[k].fim) || '';
}

