V.ofertas.forEach(o => {
  const t = textos.ofertas[o.k], hoje = /hoje/i.test(o.quando);
  ['titulo', 'subtitulo', 'chamada', 'selo'].forEach(c => {
    let v = tvGuarda(t[c], valores, `oferta ${o.produto}`, trava);
    if (!hoje && URG.test(v)) { trava.push(`oferta ${o.produto}: tirei a urgência "${v}" (você não disse que é só hoje)`); v = ''; }
