// Confere cada passo do teste; se algo não bateu, o node fica vermelho dizendo o quê.
const l = $('👉 Guarda os links').first().json, st = $('🚦 Ficou pronto?').first().json;
const j = x => { if (typeof x.data === 'string') { try { return JSON.parse(x.data); } catch (e) { return { texto: x.data }; } } return x; };
const tv = String($('🌐 Abre a TV').first().json.data || ''), p1 = j($('🌐 TV pergunta (1ª vez)').first().json), pr = j($('🌐 Dono muda preços').first().json);
const p2 = j($('🌐 TV pergunta de novo').first().json), av = j($('🌐 Dono troca os avisos').first().json), pe = j($('🌐 Dono força o almoço').first().json);
const of = j($('🌐 Dono cria oferta com IA').first().json), p3 = j($('🌐 TV pergunta depois da oferta').first().json), ct = j($('🌐 Controle em dados').first().json);
const errada = j($('🌐 Chave errada').first().json), man = j($('🌐 Abre o app (manifesto)').first().json), motor = String($('🌐 Abre o motor').first().json.data || ''), ico = $('🌐 Abre o ícone').first().json;
const falhas = [], ok = (c, m) => { if (!c) falhas.push(m); };
const itens = d => (d && d.categorias ? d.categorias.flatMap(c => c.itens) : []);
const item = (d, n) => itens(d).find(i => i.nome === n) || {};
ok(st.etapa === 'pronto' && st.categorias === 5 && st.itens === 13 && st.ofertas === 2, 'A TV não ficou pronta com 5 categorias, 13 itens e 2 ofertas: ' + JSON.stringify(st).slice(0, 300));
ok(st.grade && Object.keys(st.grade).length === 3, 'A grade devia ter os 3 períodos abertos (café, almoço, tarde): ' + JSON.stringify(st.grade));
ok(st.grade && (st.grade['Café da manhã'] || []).includes('Pães') && (st.grade['Almoço'] || []).includes('Almoço') && !(st.grade['Café da manhã'] || []).includes('Almoço'),
  'A organizadora devia pôr Pães no café da manhã e o Almoço só no almoço: ' + JSON.stringify(st.grade));
ok(tv.includes('Padaria Pão Quente') && tv.includes('tela-dados') && tv.includes('"orientacao":"horizontal"') && !tv.includes(l.controle.split('chave=')[1]), 'A página da TV não veio certa (ou mostrou a chave do controle)');
ok(p1.ok && p1.versao === 1 && p1.dados && item(p1.dados, 'Pão francês').preco === 0.8, 'A TV devia receber a versão 1 com o pão a R$ 0,80: ' + JSON.stringify(p1).slice(0, 200));
ok(pr.ok && pr.versao === 2 && pr.mudou === 2, 'Mudar 2 itens devia subir para a versão 2: ' + JSON.stringify(pr));
ok(p2.ok && p2.versao === 2 && item(p2.dados, 'Pão francês').preco === 0.9 && item(p2.dados, 'Coxinha').esgotado === true, 'A TV devia receber o pão a R$ 0,90 e a coxinha esgotada: ' + JSON.stringify(p2).slice(0, 200));
ok(av.ok && av.avisos === 2 && pe.ok && pe.periodo === 'almoco', 'Avisos/período não salvaram: ' + JSON.stringify([av, pe]));
ok(of.ok && of.oferta && of.oferta.por === 8 && of.oferta.de === 10 && of.oferta.titulo, 'A oferta com IA falhou: ' + JSON.stringify(of).slice(0, 300));
const reais = ((of.oferta && [of.oferta.titulo, of.oferta.subtitulo, of.oferta.chamada, of.oferta.selo].join(' ')) || '').match(/R\$\s?\d[\d.]*(,\d{1,2})?/g) || [];
ok(of.ok && reais.every(x => [8, 10].includes(Number(x.replace(/[^\d,]/g, '').replace(',', '.')))), 'A oferta com IA citou um preço que não é o do dono: ' + JSON.stringify(of.oferta));
ok(p3.ok && p3.versao === 5 && p3.dados.ofertas.length === 3 && p3.dados.periodo_forcado === 'almoco' && p3.dados.avisos.length === 2, 'A TV devia receber a versão 5 com 3 ofertas, almoço forçado e 2 avisos: ' + JSON.stringify(p3).slice(0, 300));
ok(ct.tvs && ct.tvs.some(x => x.nome === 'Balcão' && x.ligada), 'O controle devia mostrar a TV "Balcão" ligada: ' + JSON.stringify(ct.tvs));
ok(!ct.chave && ct.itens && ct.itens.length === 13, 'O controle em dados não pode mostrar a chave e devia ter 13 itens');
ok(errada.ok === false && /chave/i.test(errada.erro || ''), 'Chave errada devia ser recusada: ' + JSON.stringify(errada));
ok(man.name && man.display === 'fullscreen' && man.orientation === 'landscape', 'O manifesto do app não veio certo: ' + JSON.stringify(man).slice(0, 200));
ok(motor.includes('caches.open') && motor.includes('tv-'), 'O motor (service worker) não veio');
ok(Number(ico.statusCode) === 200 && /image\/png/.test(JSON.stringify(ico.headers || {})), 'O ícone não veio');
if (falhas.length) throw new Error(falhas.join(' | '));
return [{ json: { '✅': `TV pronta em ${st.segundos} s (${st.categorias} categorias, ${st.itens} itens, ${st.ofertas} ofertas, ${st.imagens} fotos da IA); preço e esgotado chegaram na TV (versão 2), avisos, almoço forçado e oferta nova com IA (versão 5); TV "Balcão" ligada no controle; chave errada recusada; app e motor ok`,
  '📺 TV': l.link, '📱 controle': l.controle, '⏰ grade': JSON.stringify(st.grade), '✨ oferta da IA': `${of.oferta.selo} · ${of.oferta.titulo} — ${of.oferta.subtitulo || ''}` } }];
